// <onek>/<yaprak> -> cikis
const leaf = msg.topic.split('/').pop();
const idx = {telemetry: 0, event: 1, status: 2, settings: 3, info: 4, anomaly: 5}[leaf];
if (idx === undefined) return null;
const out = [null, null, null, null, null, null];
out[idx] = msg;
return out;

const d = msg.payload;
if (typeof d !== 'object' || d === null) return null;

const ts = d.ts ? d.ts * 1000 : Date.now();
const zaman = new Date(ts).toLocaleString('tr-TR', {timeZone: 'Europe/Istanbul'});
const alarms = (d.alarms || []);
const tempTxt = d.temp === null ? 'HATA' : d.temp.toFixed(2);

const tempSeries = [];
if (d.temp !== null) tempSeries.push({topic: 'Sıcaklık (°C)', payload: d.temp});
tempSeries.push({topic: 'Set', payload: d.tset});

const vibSeries = [
    {topic: 'Toplam (g)', payload: d.v},
    {topic: 'X', payload: d.vx},
    {topic: 'Y', payload: d.vy},
    {topic: 'Z', payload: d.vz},
    {topic: 'Set', payload: d.vset},
];

const MODES = ['Öğreniyor', 'Duruş', 'Hareket'];
const anomCodes = alarms.filter(c => c[0] === 'A');
const anomTxt = d.ast === undefined ? '-'
    : MODES[d.ast] + (d.ast > 0 ? '  ·  z = ' + Number(d.az).toFixed(1) : '')
      + (anomCodes.length ? '  ·  ANOMALİ: ' + anomCodes.join(', ') : '');

const alarmTxt = alarms.length ? 'AKTİF: ' + alarms.join(', ') : 'Yok';

// Gunluk CSV kaydi (Node-RED kullanici klasoru altinda)
const day = new Date(ts).toLocaleDateString('sv-SE', {timeZone: 'Europe/Istanbul'});
const dir = path.join(os.homedir(), 'stm32iot_kayit');
const filename = path.join(dir, day + '.csv');
let header = '';
if (flow.get('csvFile') !== filename) {
    flow.set('csvFile', filename);
    if (!fs.existsSync(filename)) header = 'zaman;sicaklik_C;titresim_x_g;titresim_y_g;titresim_z_g;titresim_toplam_g;alarmlar\n';
}
const num = v => (v === null || v === undefined) ? '' : String(v).replace('.', ',');
const line = header + [zaman, num(d.temp), num(d.vx), num(d.vy), num(d.vz), num(d.v), alarms.join(' ')].join(';');

return [
    {payload: d.temp === null ? 0 : d.temp},
    {payload: d.v},
    tempSeries,   // dizi: ayni cikistan birden fazla mesaj
    vibSeries,
    {payload: tempTxt + ' °C  /  ' + d.v.toFixed(3) + ' g'},
    {payload: alarmTxt},
    {payload: zaman},
    {payload: line, filename: filename},
    {payload: anomTxt},
];

const e = msg.payload;
if (typeof e !== 'object' || e === null) return null;

const ts = e.ts ? e.ts * 1000 : Date.now();
const zaman = new Date(ts).toLocaleString('tr-TR', {timeZone: 'Europe/Istanbul'});
const STATE = {BASLADI: 'Başladı', BITTI: 'Bitti', BILGI: 'Bilgi'};
const dec = e.code === 'E01' ? 2 : 3;
const fmt = v => (v === null || v === undefined) ? '-' : Number(v).toFixed(dec);

const row = {
    'Zaman': zaman,
    'Kod': e.code,
    'Durum': STATE[e.state] || e.state,
    'Değer': fmt(e.value),
    'Limit': fmt(e.limit),
    'Açıklama': e.desc,
};
const list = flow.get('events') || [];
list.unshift(row);
if (list.length > 200) list.length = 200;
flow.set('events', list);

let note = null;
if (e.state === 'BASLADI') {
    note = {payload: `${e.code} ${e.desc} (değer ${fmt(e.value)}, limit ${fmt(e.limit)}) - ${zaman}`};
}

const dir = path.join(os.homedir(), 'stm32iot_kayit');
const filename = path.join(dir, 'olaylar.csv');
let header = fs.existsSync(filename) ? '' : 'zaman;kod;durum;deger;limit;aciklama\n';
const num = v => (v === null || v === undefined) ? '' : String(v).replace('.', ',');
const line = header + [zaman, e.code, e.state, num(e.value), num(e.limit), e.desc].join(';');

return [{payload: list}, note, {payload: line, filename: filename}];

const online = String(msg.payload) === 'online';
const zaman = new Date().toLocaleString('tr-TR', {timeZone: 'Europe/Istanbul'});
return {payload: (online ? 'Çevrimiçi' : 'ÇEVRİMDIŞI') + ' (' + zaman + ')'};

const s = msg.payload || {};
flow.set('settings', s);
return [
    {payload: {tset: s.tset, vset: s.vset, logint: s.logint}},
    {payload: `Sıcaklık ${Number(s.tset).toFixed(1)} °C  |  Titreşim ${Number(s.vset).toFixed(3)} g  |  ESP32 kayıt aralığı ${s.logint} s`},
];

const p = msg.payload || {};
const t = Number(p.tset), v = Number(p.vset), li = Math.round(Number(p.logint));
const err = [];
if (!(t >= -55 && t <= 125)) err.push('sıcaklık -55..125 °C olmalı');
if (!(v >= 0.001 && v <= 16)) err.push('titreşim 0.001..16 g olmalı');
if (!(li >= 1 && li <= 3600)) err.push('kayıt aralığı 1..3600 s olmalı');
if (err.length) return [null, {payload: 'Gönderilmedi: ' + err.join(', ')}];
return [
    {payload: JSON.stringify({tset: t, vset: v, logint: li})},
    {payload: 'Set değerleri cihaza gönderildi'},
];

function influxMsg(msg, line) {
    msg.method = 'POST';
    msg.url = env.get('INFLUX_URL') + '/api/v2/write?org=' + encodeURIComponent(env.get('INFLUX_ORG'))
            + '&bucket=' + encodeURIComponent(env.get('INFLUX_BUCKET')) + '&precision=s';
    msg.headers = {'Authorization': 'Token ' + env.get('INFLUX_TOKEN'), 'Content-Type': 'text/plain; charset=utf-8'};
    msg.payload = line;
    return msg;
}
const parts = String(msg.topic || '').split('/');
const device = (parts.length >= 2 ? parts[parts.length - 2] : 'cihaz01').replace(/[ ,=]/g, '_');

// ESP32 telemetrisi -> InfluxDB satir protokolu (measurement: telemetry)
const d = msg.payload;
if (typeof d !== 'object' || d === null) return null;
const ts = d.ts ? Math.floor(d.ts) : Math.floor(Date.now() / 1000);   // NTP yoksa ts=0 gelir
const f = [];
const add = (k, v) => { if (typeof v === 'number' && isFinite(v)) f.push(k + '=' + v); };
add('temp', d.temp);
add('vx', d.vx); add('vy', d.vy); add('vz', d.vz); add('v', d.v);
add('tset', d.tset); add('vset', d.vset);
const flags = Number(d.flags) || 0;
add('flags', flags);
add('alarm_temp', (flags & 0x01) ? 1 : 0);
add('alarm_vib', (flags & 0x02) ? 1 : 0);
add('alarm_sensor', (flags & 0x04) ? 1 : 0);
add('alarm_link', (flags & 0x08) ? 1 : 0);
// Uc birim anomali tespiti (ESP32 FW 1.4+): mod (0 ogreniyor, 1 durus, 2 hareket), z-skoru, A01-A04
add('ast', d.ast); add('az', d.az);
add('anom_shock', (flags & 0x10) ? 1 : 0);
add('anom_idle', (flags & 0x20) ? 1 : 0);
add('anom_ride', (flags & 0x40) ? 1 : 0);
add('anom_temp', (flags & 0x80) ? 1 : 0);
if (!f.length) return null;
return influxMsg(msg, 'telemetry,device=' + device + ' ' + f.join(',') + ' ' + ts);

function influxMsg(msg, line) {
    msg.method = 'POST';
    msg.url = env.get('INFLUX_URL') + '/api/v2/write?org=' + encodeURIComponent(env.get('INFLUX_ORG'))
            + '&bucket=' + encodeURIComponent(env.get('INFLUX_BUCKET')) + '&precision=s';
    msg.headers = {'Authorization': 'Token ' + env.get('INFLUX_TOKEN'), 'Content-Type': 'text/plain; charset=utf-8'};
    msg.payload = line;
    return msg;
}
const parts = String(msg.topic || '').split('/');
const device = (parts.length >= 2 ? parts[parts.length - 2] : 'cihaz01').replace(/[ ,=]/g, '_');

// ESP32 olayi -> InfluxDB (measurement: event)
const e = msg.payload;
if (typeof e !== 'object' || e === null) return null;
const ts = e.ts ? Math.floor(e.ts) : Math.floor(Date.now() / 1000);
const str = s => '"' + String(s === undefined || s === null ? '' : s).replace(/\\/g, '\\\\').replace(/"/g, '\\"') + '"';
const f = ['code=' + str(e.code), 'state=' + str(e.state), 'desc=' + str(e.desc)];
if (typeof e.value === 'number' && isFinite(e.value)) f.push('value=' + e.value);
if (typeof e.limit === 'number' && isFinite(e.limit)) f.push('limit=' + e.limit);
return influxMsg(msg, 'event,device=' + device + ',ecode=' + String(e.code).replace(/[ ,=]/g, '_') + ' ' + f.join(',') + ' ' + ts);

const ok = msg.statusCode >= 200 && msg.statusCode < 300;
const t = new Date().toLocaleTimeString('tr-TR', {timeZone: 'Europe/Istanbul'});
if (ok) {
    node.status({fill: 'green', shape: 'dot', text: 'yazıldı ' + t});
} else {
    node.status({fill: 'red', shape: 'ring', text: 'HATA ' + (msg.statusCode || 'bağlantı yok') + ' ' + t});
    node.warn('InfluxDB yazma hatası: ' + msg.statusCode + ' ' + String(msg.payload).slice(0, 200));
}
return null;

const a = msg.payload;
if (typeof a !== 'object' || a === null) return null;
flow.set('anomaly', a);

const MODES = ['Öğreniyor', 'Duruş', 'Hareket'];
const src = a.manual ? 'Manuel değerler' : 'Otomatik (' + a.learnMin + ' dk öğrenme)';
const st = a.mode === 0 ? 'Öğreniyor %' + Math.floor(a.learn * 100) : MODES[a.mode];
const peak = Number(a.peakLim).toFixed(3);
const ride = a.manual ? 'sefer ≤ ' + a.rideMax + ' s, tepe ≤ ' + peak + ' g'
    : a.rides >= 10 ? a.rides + ' sefer öğrenildi, sefer ≤ ' + a.rideMax + ' s, tepe ≤ ' + peak + ' g'
    : 'sefer ≤ ' + a.rideMax + ' s, tepe kontrolü ' + a.rides + '/10 seferden sonra';
const txt = src + '  ·  ' + st + '  ·  duruş ' + Number(a.mu).toFixed(4) + ' g, σ ' + Number(a.sigma).toFixed(4) + ' g  ·  ' + ride;

const key = [a.manual, a.learnMin, a.rideMax, peak].join('|');
if (flow.get('anomalyKey') === key) return [{payload: txt}, null, null];
flow.set('anomalyKey', key);
return [
    {payload: txt},
    {payload: {learnmin: a.learnMin, onay: false}},
    a.manual ? {payload: {man_mu: a.mu, man_sigma: a.sigma, man_ridemax: a.rideMax, man_peak: Number(peak)}} : null,
];

const p = msg.payload || {};
const m = Math.round(Number(p.learnmin));
if (!(m >= 1 && m <= 240)) return [null, {payload: 'Gönderilmedi: öğrenme süresi 1..240 dk olmalı'}];
if (!p.onay) return [null, {payload: 'Gönderilmedi: onay kutusunu işaretleyin'}];
return [
    {payload: JSON.stringify({learnmin: m})},
    {payload: 'Otomatik öğrenme başlatıldı: ' + m + ' dk. Bu sürede karta dokunmayın.'},
];

const a = flow.get('anomaly');
if (!a) return null;
const peak = Number(a.peakLim) > 0 ? Number(a.peakLim) : Math.max(a.mu + 20 * a.sigma, 0.05);
return {payload: {
    man_mu: Number(Number(a.mu).toFixed(4)),
    man_sigma: Number(Number(a.sigma).toFixed(4)),
    man_ridemax: a.rideMax,
    man_peak: Number(peak.toFixed(3)),
}};

// ESP32 ile ayni kurallar (applyManualAnomaly)
const p = msg.payload || {};
const mu = Number(p.man_mu), sg = Number(p.man_sigma), rm = Math.round(Number(p.man_ridemax)), pk = Number(p.man_peak);
const err = [];
if (!(mu >= 0 && mu <= 2)) err.push('ortalama 0..2 g');
if (!(sg >= 0.0005 && sg <= 1)) err.push('sapma 0.0005..1 g');
if (!(rm >= 5 && rm <= 3600)) err.push('sefer 5..3600 s');
if (!(pk > mu && pk <= 16)) err.push('tepe sınırı ortalamadan büyük ve en fazla 16 g');
if (err.length) return [null, {payload: 'Gönderilmedi: ' + err.join(', ')}];
return [
    {payload: JSON.stringify({man_mu: mu, man_sigma: sg, man_ridemax: rm, man_peak: pk})},
    {payload: 'Manuel değerler cihaza gönderildi'},
];

// Deney isaretleri: baslangic, uyaran (her deneme), bitis.
// InfluxDB "experiment" olcumune ms hassasiyetle ve ~/stm32iot_kayit/deneyler.csv dosyasina yazilir.
// Analiz: deney/analiz.js bu isaretleri ESP32 olaylariyla eslestirir.
const TYPES = {A01: 'A01 Ani darbe', A02: 'A02 Duruşta anormal titreşim', A03: 'A03 Anormal sefer',
               A04: 'A04 Hızlı ısınma', NORMAL: 'Uzun süreli normal çalışma', KESINTI: 'İnternet kesintisi'};
const now = Date.now();
const tr = t => new Date(t).toLocaleString('tr-TR', {timeZone: 'Europe/Istanbul'});
const note = s => [null, null, null, {payload: s}];
let exp = flow.get('experiment') || null;
let phase;

if (typeof msg.payload === 'object' && msg.payload !== null) {
    if (exp) return note('Önce aktif deneyi bitirin (Deney ' + exp.no + ').');
    const p = msg.payload;
    const no = Math.round(Number(p.deney_no));
    if (!(no >= 1)) return note('Deney no 1 veya büyük olmalı');
    if (!TYPES[p.tur]) return note('Deney türünü seçin');
    exp = {no, type: p.tur, severity: String(p.siddet || ''), cond: String(p.kosul || ''), start: now, trials: 0};
    phase = 'start';
} else if (msg.payload === 'stimulus') {
    if (!exp) return note('Aktif deney yok: önce deneyi başlatın');
    // Cift tiklama korumasi: 1,5 s icinde gelen ikinci isaret ayni uyarandir
    if (exp.lastStim && now - exp.lastStim < 1500) return note('Yok sayıldı: önceki işaretten 1,5 sn geçmedi');
    exp.lastStim = now;
    exp.trials++;
    phase = 'stimulus';
} else if (msg.payload === 'end') {
    if (!exp) return note('Aktif deney yok');
    phase = 'end';
} else {
    return null;
}

const tag = s => String(s).replace(/[ ,=]/g, '_');
const str = s => '"' + String(s).replace(/\\/g, '\\\\').replace(/"/g, '\\"') + '"';
const line = 'experiment,exp=' + exp.no + ',type=' + tag(exp.type) + ' phase=' + str(phase)
    + ',trial=' + (phase === 'stimulus' ? exp.trials : 0) + 'i,severity=' + str(exp.severity)
    + ',cond=' + str(exp.cond) + ' ' + now;
const influx = {
    method: 'POST',
    url: env.get('INFLUX_URL') + '/api/v2/write?org=' + encodeURIComponent(env.get('INFLUX_ORG'))
        + '&bucket=' + encodeURIComponent(env.get('INFLUX_BUCKET')) + '&precision=ms',
    headers: {'Authorization': 'Token ' + env.get('INFLUX_TOKEN'), 'Content-Type': 'text/plain; charset=utf-8'},
    payload: line,
};

const filename = path.join(os.homedir(), 'stm32iot_kayit', 'deneyler.csv');
const header = fs.existsSync(filename) ? '' : 'zaman_iso;zaman;deney_no;tur;asama;deneme;siddet;kosul\n';
const csv = header + [new Date(now).toISOString(), tr(now), exp.no, exp.type, phase,
    phase === 'stimulus' ? exp.trials : '', exp.severity.replace(/;/g, ','), exp.cond.replace(/;/g, ',')].join(';');

let info;
if (phase === 'start') info = 'Deney ' + exp.no + ' başladı: ' + TYPES[exp.type];
else if (phase === 'stimulus') info = 'Deney ' + exp.no + ': uyaran ' + exp.trials + ' işaretlendi';
else info = 'Deney ' + exp.no + ' bitti (' + exp.trials + ' uyaran)';

const state = phase === 'end' ? 'Aktif deney yok (son: Deney ' + exp.no + ', ' + exp.trials + ' uyaran)'
    : 'AKTİF: Deney ' + exp.no + ' · ' + TYPES[exp.type] + ' · ' + exp.trials + ' uyaran · başlangıç ' + tr(exp.start);
flow.set('experiment', phase === 'end' ? null : exp);
return [{payload: state}, influx, {payload: csv, filename}, {payload: info}];
